function build() {
  const enCatalog = {};
  const zhCatalog = {};
  const seen = new Set();
  for (const [key, en, zh, desc, placeholders] of ENTRIES) {
    if (seen.has(key)) throw new Error(`Duplicate key: ${key}`);
    seen.add(key);
    const entryEn = placeholders ? { message: en, description: desc, placeholders } : { message: en, description: desc };
    const entryZh = placeholders ? { message: zh, description: desc, placeholders } : { message: zh, description: desc };
    enCatalog[key] = entryEn;
    zhCatalog[key] = entryZh;
  }
  const enKeys = new Set(Object.keys(enCatalog));
  const zhKeys = new Set(Object.keys(zhCatalog));
  const enOnly = [...enKeys].filter(k => !zhKeys.has(k));
  const zhOnly = [...zhKeys].filter(k => !enKeys.has(k));
  if (enOnly.length || zhOnly.length) throw new Error(`Key mismatch! en-only: ${enOnly}, zh-only: ${zhOnly}`);
  mkdirSync(join(LOCALES_DIR, "en"), { recursive: true });
  mkdirSync(join(LOCALES_DIR, "zh_TW"), { recursive: true });
  const enPath = join(LOCALES_DIR, "en", "messages.json");
  const zhPath = join(LOCALES_DIR, "zh_TW", "messages.json");
  writeFileSync(enPath, JSON.stringify(enCatalog, null, 2) + '\n');
  writeFileSync(zhPath, JSON.stringify(zhCatalog, null, 2) + '\n');
  console.log(`Wrote ${enPath} (${Object.keys(enCatalog).length} keys)`);
  console.log(`Wrote ${zhPath} (${Object.keys(zhCatalog).length} keys)`);
  console.log(`Key sets identical: ${enKeys.size === zhKeys.size && [...enKeys].every(k => zhKeys.has(k))}`);
}

build();
